    /** @return array<string, array{secao: string, grupo: string, texto: string, base: string, gravidade: ?string, artigos: ?string, tipo: string}> */
    public static function daSecao(string $secao): array
    {
        return array_filter(self::ITENS, static fn (array $item): bool => $item['secao'] === $secao);
    }

    public static function existeSecao(string $secao): bool
    {
        return array_key_exists($secao, self::SECOES);
    }
